mkdir -p /tmp/cdp && cat > /tmp/cdp/cdp_client.rb <<'EOF'
require "socket"
require "json"
require "uri"
require "net/http"
require "websocket/driver"

# A minimal Chrome DevTools Protocol client, enough to drive a real headless Chromium from Ruby.
class CDP
  attr_reader :url, :dialogs, :js_errors
  attr_accessor :accept_next_dialog

  def initialize(ws_url)
    @url = ws_url
    uri = URI(ws_url)
    @socket = TCPSocket.new(uri.host, uri.port)
    @driver = WebSocket::Driver.client(self)
    @pending = {}
    @mutex = Mutex.new
    @id = 0
    @dialogs = []
    @js_errors = []
    @accept_next_dialog = true
    @open = false
    @driver.on(:open) { @open = true }
    @driver.on(:message) { |e| handle(JSON.parse(e.data)) }
    @driver.start
    @reader = Thread.new do
      loop do
        data = @socket.readpartial(65_536)
        @driver.parse(data)
      end
    rescue EOFError, IOError, Errno::ECONNRESET
      nil
    end
    sleep 0.05 until @open
  end

  def write(data)
    @socket.write(data)
  end

  def command(method, params = {})
    id = @mutex.synchronize { @id += 1 }
    queue = Queue.new
    @mutex.synchronize { @pending[id] = queue }
    @driver.text({ id: id, method: method, params: params }.to_json)
    response = queue.pop
    raise "CDP #{method} failed: #{response['error']}" if response["error"]

    response["result"]
  end

  def evaluate(expression)
    result = command("Runtime.evaluate", expression: expression, returnByValue: true, awaitPromise: true)
    raise "JS error: #{result['exceptionDetails']}" if result["exceptionDetails"]

    result.dig("result", "value")
  end

  def wait_until(timeout: 10, &)
    deadline = Time.now + timeout
    loop do
      value = yield
      return value if value
      raise "timed out waiting (last value: #{value.inspect})" if Time.now > deadline

      sleep 0.1
    end
  end

  private
    def handle(message)
      if message["id"]
        queue = @mutex.synchronize { @pending.delete(message["id"]) }
        queue&.push(message)
      elsif message["method"] == "Page.javascriptDialogOpening"
        @dialogs << message["params"]
        accept = @accept_next_dialog
        # Answer on another thread: the page is blocked inside confirm() until this is handled
        Thread.new { command("Page.handleJavaScriptDialog", accept: accept) }
      elsif message["method"] == "Runtime.exceptionThrown"
        @js_errors << message.dig("params", "exceptionDetails", "text")
      end
    end
end

class Browser
  PORT = 9333

  def initialize
    @pid = Process.spawn("chromium", "--headless=new", "--no-sandbox", "--disable-gpu", "--remote-allow-origins=*",
      "--remote-debugging-port=#{PORT}", "--user-data-dir=/tmp/cdp/profile", "--window-size=1280,1000", "about:blank",
      out: "/tmp/cdp/chromium.log", err: "/tmp/cdp/chromium.log")
    page = wait_for_page
    @cdp = CDP.new(page["webSocketDebuggerUrl"])
    @cdp.command("Page.enable")
    @cdp.command("Runtime.enable")
  end

  def cdp = @cdp

  def close
    Process.kill("TERM", @pid) rescue nil
  end

  def set_cookie(name, value, url)
    @cdp.command("Network.enable")
    @cdp.command("Network.setCookie", name: name, value: value, url: url, httpOnly: true, sameSite: "Lax")
  end

  def visit(url)
    @cdp.command("Page.navigate", url: url)
    wait_for_ready
  end

  def wait_for_ready
    @cdp.wait_until { @cdp.evaluate("document.readyState === 'complete' && !!document.body") }
    sleep 0.3
  end

  def path = @cdp.evaluate("location.pathname")

  def wait_for_path(expected)
    @cdp.wait_until(timeout: 15) { path == expected && (sleep(0.2) || true) } rescue
      raise("expected path #{expected}, was #{path}")
  end

  def click_selector(selector)
    @cdp.evaluate(<<~JS)
      (() => { const el = document.querySelector(#{selector.to_json}); if (!el) throw new Error("missing #{selector}"); el.click(); return true })()
    JS
  end

  # Clicks the first element matching a selector whose text matches `text`
  def click_text(selector, text)
    @cdp.evaluate(<<~JS)
      (() => {
        const el = [...document.querySelectorAll(#{selector.to_json})].find(e => e.textContent.trim().includes(#{text.to_json}) || (e.getAttribute("aria-label") || "").includes(#{text.to_json}));
        if (!el) throw new Error("no #{selector} with text #{text}");
        el.click(); return true
      })()
    JS
  end

  def type_into(selector, text)
    @cdp.evaluate("document.querySelector(#{selector.to_json}).focus()")
    @cdp.command("Input.insertText", text: text)
  end

  private
    def wait_for_page
      Net::HTTP.start("127.0.0.1", PORT) { }
      targets = nil
      20.times do
        begin
          targets = JSON.parse(Net::HTTP.get(URI("http://127.0.0.1:#{PORT}/json/list")))
          page = targets.find { |t| t["type"] == "page" }
          return page if page
        rescue Errno::ECONNREFUSED
        end
        sleep 0.5
      end
      raise "chromium did not start"
    end
end
